def sha256_file(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def verify_oii014_contract() -> None:
    if not SOURCE_OII014.is_file():
        raise FileNotFoundError(f"Actual OII-014 module missing: {SOURCE_OII014}")
    source = SOURCE_OII014.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "OII-014"',
        "class ControlledScientificReasoningInvocationManifest",
        "def verify_controlled_scientific_reasoning_invocation_manifest",
        "invocation_manifest_hash",
        "invocation_manifest_materialized",
        "callable_resolution_allowed",
        "callable_binding_allowed",
        "reasoning_execution_allowed",
        "probability_estimation_allowed",
        "final_intelligence_conclusion_allowed",
        "qseries_execution_allowed",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(
            "Actual OII-014 contract mismatch; missing: "
            + ", ".join(missing)
        )
    print("[OK] Actual OII-014 controlled invocation manifest verified")


def verify_complete_lineage() -> dict[Path, str]:
    hashes: dict[Path, str] = {}
    for path in PROTECTED_MODULES:
        if not path.is_file():
            raise FileNotFoundError(f"Required OII lineage module missing: {path}")
        ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        hashes[path] = sha256_file(path)
    print("[OK] Actual OII-003 through OII-014 module lineage verified")
    return hashes


def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def append_export(path: Path, line: str) -> None:
    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    if line in existing.splitlines():
        print(f"[OK] PACKAGE EXPORT PRESENT: {path.resolve()}")
        return
    if existing and not existing.endswith("\n"):
        existing += "\n"
    path.write_text(existing + line + "\n", encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] PACKAGE UPDATED: {path.resolve()}")


def assert_protected_unchanged(before: dict[Path, str], phase: str) -> None:
    changed = [
        str(path)
        for path, digest in before.items()
        if not path.is_file() or sha256_file(path) != digest
    ]
    if changed:
        raise RuntimeError(
            f"Protected OII lineage changed during {phase}: "
            + ", ".join(changed)
        )
    print(f"[PASS] Protected OII-003 through OII-014 unchanged {phase}")


def main() -> int:
    print("========================================")
    print(" OII-015 INSTALLER")
    print(" FINAL CERTIFICATION AND FREEZE GATE")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit(
            "[ERROR] Run this installer from the kalshi-qss-bot repository root."
        )

    verify_oii014_contract()
    protected_hashes = verify_complete_lineage()

    write_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_replacement(TEST, TEST_SOURCE)
    append_export(
        PACKAGE_INIT,
        "from .oracle_integrated_intelligence_final_certification_freeze_gate import *",
    )

    assert_protected_unchanged(protected_hashes, "during installation")

    completed = subprocess.run(
        [sys.executable, str(TEST)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode:
        raise SystemExit(completed.returncode)

    assert_protected_unchanged(protected_hashes, "after terminal certification")
    print("[PASS] No acquisition module modified")
    print("[PASS] No analytics module modified")
    print("[PASS] No Oracle Operator module modified")
    print("[PASS] No Q Series execution module modified")
    print("[OK] OII-015 terminal test executed automatically")
    print("[DONE] OII INTEGRATED INTELLIGENCE CERTIFIED AND FROZEN")
    print("")
    print("NEXT SUBSYSTEM")
    print("  Oracle scientific reasoning implementations")
    print("  - callable registry")
    print("  - discipline adapters")
    print("  - controlled read-only execution")
    print("  - synthesized intelligence products")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
